// O pedido de saúde não tem corpo: a assinatura cobre "carimbo." (corpo vazio).
const carimbo = Math.floor(Date.now() / 1000);
return [{ json: { corpo: '', carimbo, mensagem: `${carimbo}.` } }];

// Decide o que fazer com a resposta de /webhooks/n8n/saude. Cada incidente liga a
// parada total uma vez só (quem desliga é uma pessoa, com reautenticação) e o aviso
// se repete a cada 30 minutos enquanto durar.
const LIMITE_SEM_SINAL_S = 180;
const REAVISO_MS = 30 * 60 * 1000;

const agora = Date.now();
const escaparHtml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const estado = $getWorkflowStaticData('global');
const r = $input.first().json || {};
const hora = (ms) =>
  new Date(ms).toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });

let situacao = 'ok';
if (r.error !== undefined || !('motorVivoHaSegundos' in r)) situacao = 'api_fora';
else if (typeof r.motorVivoHaSegundos !== 'number' || r.motorVivoHaSegundos > LIMITE_SEM_SINAL_S) situacao = 'motor_parado';

const incidente = estado.incidente || null;

if (situacao === 'ok') {
  if (!incidente) return [];
  estado.incidente = null;
  const texto =
    incidente.tipo === 'motor_parado'
      ? 'O motor voltou a dar sinal. A parada total continua ligada: confira o que aconteceu e desligue pela tela quando for seguro.'
      : 'A API voltou a responder ao vigia de saúde.';
  return [{ json: { ligarParada: false, texto: escaparHtml(texto) } }];
}

if (incidente && incidente.tipo === situacao) {
  if (agora - incidente.ultimoAvisoEm < REAVISO_MS) return [];
  estado.incidente = { ...incidente, ultimoAvisoEm: agora };
  const oQue = situacao === 'motor_parado' ? 'O motor continua sem dar sinal' : 'A API continua sem responder';
  return [{ json: { ligarParada: false, texto: escaparHtml(`${oQue} desde ${hora(incidente.desde)}.`) } }];
}

estado.incidente = { tipo: situacao, desde: agora, ultimoAvisoEm: agora };
if (situacao === 'motor_parado') {
  const ha =
    typeof r.motorVivoHaSegundos === 'number'
      ? `há ${Math.round(r.motorVivoHaSegundos)} s`
      : 'desde que a API subiu';
  return [
    {
      json: {
        ligarParada: true,
        texto: escaparHtml(`ALERTA: o motor está sem dar sinal ${ha} (limite: ${LIMITE_SEM_SINAL_S} s). Robôs pausados: ${r.robosPausados ?? '?'}.`),
      },
    },
  ];
}
return [
  {
    json: {
      ligarParada: false,
      texto:
        'ALERTA: a API não respondeu ao vigia de saúde. Sem ela não dá para ligar a parada total por aqui: confira o servidor agora.',
    },
  },
];

// Junta o resultado de POST /api/v1/parada-total ao aviso.
const escaparHtml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const r = $input.first().json || {};
const base = $('Avaliar saúde').first().json.texto;
const texto =
  r.ligada === true
    ? `${base}\nLiguei a parada total: nenhuma ordem sai até alguém desligá-la pela tela.`
    : `${base}\nNÃO consegui ligar a parada total (${escaparHtml(r.error ? r.error.message || 'erro' : 'resposta inesperada')}). Ligue pela tela agora.`;
return [{ json: { texto } }];
